import json
from datetime import datetime
from os import path, makedirs
from base64 import b64encode
import zipfile

from taf.vran.vdu.enb.rest.client import HttpClient
from taf.vran.vdu.enb.rest.utilities.connection_details import ConnectionDetails
from taf.vran.vdu.enb.rest.utilities.multipart_encoder import MultipartEncoder
from taf.vran.vdu.enb.rest.utilities.poll_status import poll_status


class ASMv1(HttpClient):
    def __init__(self, base_url: str, connection_details: ConnectionDetails) -> None:
        super().__init__(connection_details)
        self.base_url = base_url + "/api/asm/v1"

    def update_expired_password(
        self,
        new_password: str = "Nokia@123",
        account_name: str = "Nemuadmin"
    ) -> dict:
        """
        Sends a request to update the expired password.

        :param str new_password: New password to be set. Defaults to "Nokia@123".
        :param str account_name: Account name for which the password is being updated. Defaults to "Nemuadmin".

        :returns: Response of the request, for example:

            .. code-block:: python

                {
                  "summary": "Update local user account",
                  "content": "Success"
                }
        :rtype: dict
        """
        endpoint = "/account/expired-password"
        headers = {
            "X-Nokia-Username": account_name,
            "X-Nokia-Accessmode": "ro" if self.connection_details.read_only else "rw"
        }

        params = {
            "username": b64encode(self.username.encode("utf-8")).decode(),
            "password": b64encode(self.password.encode("utf-8")).decode(),
            "newPassword": b64encode(new_password.encode("utf-8")).decode()
        }

        response = self.send_request(
            method="PATCH",
            endpoint=endpoint,
            headers=headers,
            verify=False,
            data=json.dumps(params)
        )

        self.connection_details.password = new_password
        return response

    def add_plan_to_staging(self, scf_file: str, timeout: int = 30) -> dict:
        """
        Adds plan to the staging area and polls operation status until it's completed.
        Name of the plan will be the same as the name of the file.

        :param scf_file: path to plan file
        :param timeout: timeout in seconds, defaults to 30

        :returns: operation info, for example:

            .. code-block:: python

                {
                   "actionId":"a_0a18b57d-8234-4dbe-9ea7-157c4ba7994f",
                   "incorrectObjectsFeedback":[],
                   "planId":"sp_4e34e0c5-bb39-4abe-826c-591988322209",
                   "procedureState":"planMigration",
                   "ramlParsingErrors":[],
                   "status":"success"
                }
        :rtype: dict
        """
        plan_name = path.splitext(path.split(scf_file)[1])[0]

        with open(scf_file, "rb") as file:
            multipart_data = MultipartEncoder(
                fields={"planFile": (plan_name, file, "text/xml"),
                        "planName": plan_name})

            action_id = self.send_request(
                method="POST",
                endpoint="/staged-plans/actions/downloads",
                data=str(multipart_data),
                headers={"Content-Type": multipart_data.content_type},
                log_payload=False
            )["actionId"]

        return poll_status(
            instance=self,
            endpoint=f"/staged-plans/actions/downloads/{action_id}",
            timeout=timeout
        )

    def activate_validated_plan(self, plan_id: str, timeout: int = 150) -> dict:
        """
        Activates the validated plan with given plan_id and polls operation status until it's completed.

        :param plan_id: plan id, get from add_plan_to_staging
        :param timeout: timeout in seconds for the activation to complete, defaults to 150s

        :returns: activation operation info, for example:

            .. code-block:: python

                {
                   "basicReport":{
                      "activationErrors":[],
                      "commissioningType":"Full commissioning",
                      "dateAndTime":"2025-03-24T12:06:11+00:00",
                      "planActivationResult":"success",
                      "planValidationResult":"success",
                      "validationErrors":[]
                   },
                   "cmPlanId":"plan_20250324120610_43b9c171-9a58-4fa4-a714-343a9f57f80c",
                   "consistencyReport": [],
                   "id":"o_67d68b37-f63b-473f-95f6-d2174d06fc1e",
                   "procedureState":"planActivate",
                   "status":"success"
                }
        :rtype: dict
        """
        operation_id = self.send_request(
            method="POST",
            endpoint=f"/staged-plans/{plan_id}/operations/activations",
            headers=self.headers.get(content_type="json")
        )["id"]

        return poll_status(
            instance=self,
            endpoint=f"/staged-plans/{plan_id}/operations/activations/{operation_id}",
            timeout=timeout
        )

    def delete_staged_plan(self, plan_id: str) -> None:
        """
        Deletes plan with given plan_id from staging area.

        :param plan_id: plan id, get from add_plan_to_staging
        """
        self.send_request(method="DELETE", endpoint=f"/staged-plans/{plan_id}")

    def trigger_snapshot_collection(self, coverage: str) -> dict:
        """
        Trigger local snapshot collection

        :param str coverage: coverage of the snapshot, available options:
                            "full", "minor", "fullWithoutRFLogs", "minorWithoutRFLogs", "l1Files", "screl".

        :returns: operation info, for example:

            .. code-block:: python

                {
                  "filterRegx": "/([A-Z])\\w+/",
                  "reason": "Collect log to check issue.",
                  "coverage": "full",
                  "originator": "EM",
                  "operationId": "Abc123",
                  "status": "ongoing",
                  "failureInfo": "collection timeout.",
                  "ruFailureInfo": [
                    "RMOD-1/RMOD_R-1: snapshot collect failed"
                  ],
                  "files": [
                    {
                      "fileId": "a.zip",
                      "sizeInByte": 1865321
                    }
                  ]
                }
        :rtype: dict
        """
        return self.send_request(
            method="POST",
            endpoint="/snapshot/operations/locals",
            headers=self.headers.get(content_type="json"),
            data=json.dumps({"coverage": coverage})
        )

    def collect_snapshot(self, operation_id: str, timeout: int = 300) -> dict:
        """
        Collects local snapshot triggered by "trigger_snapshot_collection" method.

        :param operation_id: id of the snapshot collection operation, get from trigger_snapshot_collection
        :param timeout: timeout for the operation

        :returns: operation info, for example:

            .. code-block:: python

                {
                  "filterRegx": "/([A-Z])\\w+/",
                  "reason": "Collect log to check issue.",
                  "coverage": "full",
                  "originator": "EM",
                  "operationId": "Abc123",
                  "status": "ongoing",
                  "failureInfo": "collection timeout.",
                  "ruFailureInfo": [
                    "RMOD-1/RMOD_R-1: snapshot collect failed"
                  ],
                  "files": [
                    {
                      "fileId": "a.zip",
                      "sizeInByte": 1865321
                    }
                  ]
                }
        :rtype: dict
        """
        return poll_status(
            instance=self, endpoint=f"/snapshot/operations/locals/{operation_id}", timeout=timeout
        )

    def download_snapshot_files_and_save_to_local(
        self,
        operation_id: str,
        snapshot_files: list,
        directory: str,
        compressed: bool
    ) -> str:
        """
        Downloads snapshot files and saves them to local directory.

        :param operation_id: id of the operation to download files, get from collect_snapshot "operationId" key
        :param snapshot_files: list of files to download, get from collect_snapshot "files" key
        :param directory: local directory where the snapshot will be saved
        :param compressed: if True, the snapshot files will be compressed to zip

        :return: path to saved snapthot - to zip when compressed or "directory" if not
        :rtype: str
        """
        if not path.exists(directory):
            makedirs(directory)

        if compressed:
            return self._save_snapshot_files_to_zip(
                snapshot_files=snapshot_files,
                directory=directory,
                operation_id=operation_id
            )

        else:
            return self._save_snapshot_files(
                snapshot_files=snapshot_files,
                directory=directory,
                operation_id=operation_id
            )

    def delete_snapshot_operation(self, operation_id: str):
        """
        Deletes snapshot operation.

        :param operation_id: id of the operation to delete
        """
        endpoint = f"/snapshot/operations/locals/{operation_id}"
        self.send_request(method="DELETE", endpoint=endpoint)

    def _save_snapshot_files_to_zip(self, snapshot_files: list, directory: str, operation_id: str) -> str:
        """
        Saves all snapshot files to the zip file in the given directory.

        :param list snapshot_files: list of snapshot files, get from collect_snapshot "files" key
        :param str directory: path to where zip file with snapshot should be saved
        :param str operation_id: ID of the snapshot collection operation, get from collect_snapshot "operationId" key

        :return: path to zip file
        :rtype: str
        """
        zip_path = f"{directory}/Snapshot_{datetime.now().strftime('%Y%m%d-%H%M%S')}.zip"
        zip_buffer = zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED)

        for file in snapshot_files:
            file_id = file["fileId"]
            snapshot_file = self.send_request(
                endpoint=f"/snapshot/operations/locals/{operation_id}/files/{file_id}",
                method="GET"
            )
            zip_buffer.writestr(file_id, snapshot_file)

        zip_buffer.close()
        return zip_path

    def _save_snapshot_files(self, snapshot_files: list, directory: str, operation_id: str) -> str:
        """
        Saves all snapshot files separately in the given directory.

        :param list snapshot_files: list of snapshot files, get from collect_snapshot "files" key
        :param str directory: path to where files should be saved
        :param str operation_id: ID of the snapshot collection operation, get from collect_snapshot "operationId" key

        :return: directory where snapshot files were saved
        :rtype: str
        """
        for file in snapshot_files:
            file_id = file["fileId"]
            snapshot_file = self.send_request(
                endpoint=f"/snapshot/operations/locals/{operation_id}/files/{file_id}",
                method="GET"
            )
            with open(f"{directory}/{file_id}", "wb") as f:
                f.write(snapshot_file)

        return directory

