    def get_rmods_summary(self) -> dict:
        """
        Get summary of all Radio Modules statuses.

        :returns: summary of RMODs statuses, for example:

            .. code-block:: python

                {
                  "operationalState": {
                    "enabled": 5000,
                    "disabled": 5000
                  },
                  "availabilityStatus": {
                    "in test": 5000,
                    "failed": 5000,
                    "power off": 5000,
                    "off line": 5000,
                    "off duty": 5000,
                    "dependency": 5000,
                    "degraded": 5000,
                    "not installed": 5000,
                    "log full": 5000,
                    "on line": 5000
                  },
                  "administrativeState": {
                    "locked": 5000,
                    "unlocked": 5000
                  }
                }
        :rtype: dict
        """
        return self.send_request(
            method="GET", endpoint="/rmods/summary", headers=self.headers.get(accept="json")
        )

